        reg0[7:4] <= d[3:0];
        reg1[7:4] <= d[7:4];
        reg2[7:4] <= d[11:8];
        reg3[7:4] <= d[15:12];
      end
    end
  end

  assign q = {reg3, reg2, reg1, reg0};

endmodule

