      speed_reg <= 4'b1111;
      warning_reg <= 1'b0;
    end else begin
      speed_reg <= 4'b1111;
      warning_reg <= 1'b1;
    end
  end

  assign speed = speed_reg;
  assign warning = warning_reg;

endmodule

