description:
Implement the Verilog module based on the following description.
Build a 5-bit binary counter with synchronous active high reset signal and a load enable signal. When load is high, load the counter with the provided value.
// (1) reset: Resets the counter to 5'b00000 when high.
// (2) load: Enables the load operation when high.
// (3) load_val: The value to be loaded into the counter when load is high.
// (4) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    input load,
    input [4:0] load_val,
    output reg [4:0] q);

code:
module top_module(
    input clk,
    input reset,
    input load,
    input [4:0] load_val,
    output reg [4:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 5'b00000
            q <= 5'b00000;
        end else if (load) begin
            // Load operation: Load the counter with the provided value
            q <= load_val;
        end else begin
            // Binary counter: Increment by 1
            q <= q + 1;
        end
    end

endmodule

